const acorn=require('acorn');
const {JSDOM,VirtualConsole}=require('jsdom');
const repo=process.env.GH_REPOSITORY,token=process.env.GH_TOKEN,path='siza-mobile-test/index.html';const headers={'Accept':'application/vnd.github+json','Authorization':`Bearer ${token}`,'X-GitHub-Api-Version':'2022-11-28'},api=`https://api.github.com/repos/${repo}/contents/${path}`;const assert=(v,m)=>{if(!v)throw new Error(m)};
async function getFile(p){const r=await fetch(`https://api.github.com/repos/${repo}/contents/${p}?ref=main`,{headers});if(!r.ok)throw new Error(`${p}: GET ${r.status}`);const f=await r.json();return{sha:f.sha,text:Buffer.from(f.content.replace(/\n/g,''),'base64').toString('utf8')}}
function parse(html){const so=html.lastIndexOf('<script>'),sc=html.indexOf('</script>',so);assert(so>=0&&sc>so,'main script not found');const start=so+8,code=html.slice(start,sc),ast=acorn.parse(code,{ecmaVersion:'latest'}),decl=[];function walk(n){if(!n||typeof n!=='object')return;if(n.type==='FunctionDeclaration'&&n.id)decl.push(n);for(const[k,v]of Object.entries(n)){if(k==='start'||k==='end')continue;if(Array.isArray(v))v.forEach(walk);else if(v&&typeof v==='object'&&v.type)walk(v)}}walk(ast);return{start,sc,code,ast,decl}}
function identifierCount(ast,name){let count=0;function walk(n){if(!n||typeof n!=='object')return;if(n.type==='Identifier'&&n.name===name)count++;for(const[k,v]of Object.entries(n)){if(k==='start'||k==='end')continue;if(Array.isArray(v))v.forEach(walk);else if(v&&typeof v==='object'&&v.type)walk(v)}}walk(ast);return count}
function textCount(html,name){const esc=name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return [...html.matchAll(new RegExp(`\\b${esc}\\b`,'g'))].length}
function inlineCore(html,files){let out=html;for(const[name,text]of [['card-effects.js',files.effects],['card-schema.js',files.schema],['cards.js',files.cards],['card-renderer.js',files.renderer]]){const tag=`<script src="../siza-core/${name}"></script>`;assert(out.includes(tag),`Missing core tag ${name}`);out=out.replace(tag,`<script>${text}</script>`)}return out}
function makeDom(html,label){const vc=new VirtualConsole();vc.on('jsdomError',e=>console.error(`[JSDOM ${label}]`,e.message));return new JSDOM(html,{runScripts:'dangerously',url:'https://siza.local/siza-mobile-test/',virtualConsole:vc})}
(async()=>{const index=await getFile(path),files={effects:(await getFile('siza-core/card-effects.js')).text,schema:(await getFile('siza-core/card-schema.js')).text,cards:(await getFile('siza-core/cards.js')).text,renderer:(await getFile('siza-core/card-renderer.js')).text};console.log('Current Mobile blob '+index.sha);const names=['cardArtMarkupV1','damageRibbonHtml','effectiveBlockPanelV070','enemyPhysicalStep','manaHtml','renderMatch'],p=parse(index.text),cuts=[];for(const name of names){const nodes=p.decl.filter(n=>n.id.name===name);assert(nodes.length===1,`${name}: declarations ${nodes.length}`);assert(identifierCount(p.ast,name)===1,`${name}: AST references exist`);assert(textCount(index.text,name)===1,`${name}: text/string references exist`);cuts.push([nodes[0].start,nodes[0].end,name])}let code=p.code;for(const[start,end,name]of cuts.sort((a,b)=>b[0]-a[0]))code=code.slice(0,start)+`/* zero-reference ${name} removed */`+code.slice(end);const html=index.text.slice(0,p.start)+code+index.text.slice(p.sc),q=parse(html);assert(q.decl.length===p.decl.length-6,`Expected declaration count ${p.decl.length-6}, got ${q.decl.length}`);for(const name of names)assert(!q.decl.some(n=>n.id.name===name),`${name} remains`);const oldDom=makeDom(inlineCore(index.text,files),'old'),newDom=makeDom(inlineCore(html,files),'new');oldDom.window.setTimeout=()=>0;newDom.window.setTimeout=()=>0;const a=oldDom.window.SIZA.runArenaCriticalV071(),b=newDom.window.SIZA.runArenaCriticalV071();assert(a.passed===a.total&&b.passed===b.total,'Arena contract failure');assert(JSON.stringify(a.results.map(x=>x.pass))===JSON.stringify(b.results.map(x=>x.pass)),'Arena behavior changed');console.log(`PASS removed 6 zero-reference functions; declarations ${p.decl.length} -> ${q.decl.length}; Arena ${b.passed}/${b.total}`);oldDom.window.close();newDom.window.close();const w=await fetch(api,{method:'PUT',headers:{...headers,'Content-Type':'application/json'},body:JSON.stringify({message:'Remove six zero-reference Arena functions',content:Buffer.from(html,'utf8').toString('base64'),sha:index.sha,branch:'main'})});if(!w.ok)throw new Error(`PUT ${w.status}: ${await w.text()}`);const out=await w.json();console.log('COMMIT '+out.commit.sha)})().catch(e=>{console.error(e.stack||e.message);process.exit(1)});
